# requirements: pip install openai
# 示例用 Python 客户端调用 vLLM 的 OpenAI-compatible /v1/chat/completions
import os
from openai import OpenAI
from typing import List, Dict
import time
# 配置 —— 改成你的 vllm server 地址和 api key（若本地测试 vllm 可用 EMPTY）
BASE_URL = os.environ.get("SGLANG_BASE_URL", "http://127.0.0.1:12306/v1")
API_KEY = os.environ.get("OPENAI_API_KEY", "")  # vLLM 本地可用空字符串或 "EMPTY"

client = OpenAI(api_key=API_KEY, base_url=BASE_URL, timeout=60)

def chat_completion(messages: List[Dict[str, str]],
                    model: str = "Qwen/Qwen3-8B",
                    max_tokens: int = 32,
                    temperature: float = 0.0):
    """
    简单封装的 chat/completions 请求
    - messages: [{"role":"system","content":...}, {"role":"user","content":...}, ...]
    - model: 需要和 vLLM server 暴露的 id 一致
    """
    try:

        resp = client.chat.completions.create(
            model=model,
            messages=messages,
            max_tokens=max_tokens,
            temperature=temperature,
            agent_id="abcdefg",
            task_id=111
        )
        num_decode_tokens = resp.usage.completion_tokens
        num_prefill_tokens = resp.usage.prompt_tokens
        num_cached_tokens = resp.usage.prompt_tokens_details.cached_tokens if resp.usage.prompt_tokens_details else 0
        prefill_time = resp.prefill_time
        decode_time = resp.decode_time
        num_local_cache = resp.num_local_cache
        num_global_cache = resp.num_global_cache
        # OpenAI-compatible response：resp.choices[0].message.content
        print([num_prefill_tokens, num_decode_tokens, num_cached_tokens, prefill_time, decode_time, num_local_cache, num_global_cache])

        # 有些兼容实现可能返回 choice.message 或 choice.delta（streaming），这里取 message
        return resp
    except Exception as e:
        # 简单错误处理：根据你的部署可做更细致的重试/超时策略
        raise RuntimeError(f"chat/completions 调用失败: {e}") from e

